//! Complete frozen DTOs for ignored Python JSON scalars in nested strings.
use base64::{engine::general_purpose::STANDARD, Engine};
use localbrain_core::backend::ingest::parse_session;
use serde_json::{json, Value};
use std::fs;
#[test]
fn nested_arguments_results_and_question_wrappers_keep_ignored_python_scalars() {
    let cases: Vec<Value> = serde_json::from_str(CASES).unwrap();
    assert_eq!(cases.len(), 25);
    let temp = tempfile::Builder::new()
        .prefix("lb-native-ingest-nested-")
        .tempdir()
        .unwrap();
    fs::create_dir(temp.path().join("nested-workspace")).unwrap();
    for case in cases {
        let path = temp
            .path()
            .join("nested-workspace")
            .join(case["path"].as_str().unwrap().rsplit('/').next().unwrap());
        fs::write(
            &path,
            STANDARD.decode(case["bytes"].as_str().unwrap()).unwrap(),
        )
        .unwrap();
        let parsed = parse_session(case["provider"].as_str().unwrap(), &path)
            .unwrap_or_else(|e| panic!("{}: {e}", case["case"]))
            .unwrap();
        let mut expected = case["expected"].clone();
        expected["source_path"] = json!(path);
        assert_eq!(
            serde_json::to_value(parsed).unwrap(),
            expected,
            "{}",
            case["case"]
        );
    }
}

#[test]
fn selected_nested_surrogate_refuses_materialization_instead_of_replacing_the_url() {
    let temp = tempfile::Builder::new()
        .prefix("lb-native-ingest-selected-")
        .tempdir()
        .unwrap();
    let path = temp.path().join("selected.jsonl");
    let records = [
        json!({"type":"session_meta","payload":{"id":"selected"}}),
        json!({"type":"response_item","payload":{"type":"function_call","call_id":"selected-call","name":"atlassian.getConfluencePage","arguments":"{\"page_id\":\"77\"}"}}),
        json!({"type":"response_item","payload":{"type":"function_call_output","call_id":"selected-call","output":r#"{"page":{"url":"https://wiki.example.test/spaces/SYN/pages/77/\ud800","id":"77"}}"#}}),
    ];
    fs::write(
        &path,
        records
            .iter()
            .map(Value::to_string)
            .collect::<Vec<_>>()
            .join("\n"),
    )
    .unwrap();
    assert_eq!(
        parse_session("codex", &path).unwrap_err().code,
        "source_unicode"
    );
}

#[test]
fn fast_path_retains_fixed_decimal_conversion_refusal_and_ignores_long_digit_text() {
    let temp = tempfile::Builder::new()
        .prefix("lb-native-ingest-decimal-")
        .tempdir()
        .unwrap();
    for provider in ["claude", "codex"] {
        let path = temp.path().join(format!("{provider}.jsonl"));
        let record = if provider == "claude" {
            json!({"type":"user","sessionId":"decimal","message":{"content":"Keep message"}})
        } else {
            json!({"type":"event_msg","payload":{"type":"user_message","message":"Keep message"}})
        };
        for (digits, quoted, accepted) in [
            (4300, false, true),
            (4301, false, false),
            (4301, true, true),
        ] {
            let scalar = if quoted {
                format!("\"{}\"", "1".repeat(digits))
            } else {
                "1".repeat(digits)
            };
            let mut text = record.to_string();
            text.pop();
            text.push_str(&format!(",\"ignored\":{scalar}}}"));
            fs::write(&path, text).unwrap();
            let result = parse_session(provider, &path);
            if accepted {
                assert_eq!(result.unwrap().unwrap().events.len(), 1);
            } else {
                assert_eq!(result.unwrap_err().code, "source_scalar");
            }
        }
    }
}
